begin;
set local lock_timeout='3s';set local statement_timeout='60s';
create temporary table tecnica_test(actor uuid,company_id uuid,order_id uuid,pos_id uuid,contenuto jsonb);
insert into tecnica_test select sp.user_id,sp.company_id,o.id,gen_random_uuid(),null from public.staff_permissions sp join public.orders o on o.company_id=sp.company_id where sp.can_view_sicurezza_cantiere and not sp.sola_lettura and o.deleted_at is null and exists(select 1 from public.orders x where x.company_id=o.company_id and x.id<>o.id and x.deleted_at is null) limit 1;
grant select on tecnica_test to authenticated,service_role;
do $$begin if not exists(select 1 from tecnica_test) then raise exception 'Azienda di prova assente';end if;end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true) from tecnica_test;
update tecnica_test set contenuto='{"versione_modello": 1, "versione_controlli": 2, "versione_tecnica": 1, "formazione": [], "lavorazioni": [{"id": "l1", "titolo": "TEST SCHEDA TECNICA", "tecnica": {"area": "TEST area", "interferenze": "TEST interferenze", "condizioni_avvio": "TEST condizioni_avvio", "sospensione": "TEST sospensione", "emergenze": "TEST emergenze", "prima": "TEST prima", "durante": "TEST durante", "dopo": "TEST dopo", "riesaminata": true, "attrezzature_previste": "si", "motivo_senza_attrezzature": "", "rischi": [{"id": "r1", "pericolo": "TEST pericolo", "esposti": "TEST esposti", "situazione": "TEST situazione", "valutazione_iniziale": "TEST valutazione_iniziale", "misure_collettive": "TEST misure_collettive", "misure_organizzative": "TEST misure_organizzative", "dpi": "TEST dpi", "valutazione_residua": "TEST valutazione_residua", "riferimento": "TEST riferimento"}], "attrezzature": [{"id": "a1", "nome": "TEST nome", "identificativo": "TEST identificativo", "impiego": "TEST impiego", "controlli_preuso": "TEST controlli_preuso", "manuale_riferimento": "TEST manuale_riferimento", "formazione_addestramento": "TEST formazione_addestramento"}]}}]}'::jsonb;
create temporary table mezzo_test(a1 uuid default gen_random_uuid(),a2 uuid default gen_random_uuid(),q uuid default gen_random_uuid(),parent uuid default gen_random_uuid(),child uuid default gen_random_uuid(),fuori uuid default gen_random_uuid(),altro uuid,fonte jsonb,prova jsonb);
insert into mezzo_test(altro)select id from public.orders where company_id=(select company_id from tecnica_test) and id<>(select order_id from tecnica_test) and deleted_at is null limit 1;
grant select on mezzo_test to authenticated,service_role;
insert into public.mezzi(id,company_id,nome,tipo,assegnato_order_id,matricola,note,valore_acquisto)
select v.id,f.company_id,'TEST MEZZI POS OMONIMO',v.tipo,v.ordine,v.id::text,'TEST NOTA PRIVATA',999 from tecnica_test f cross join mezzo_test t cross join lateral(values(t.a1,'attrezzatura',f.order_id),(t.a2,'attrezzatura',f.order_id),(t.parent,'furgone',f.order_id),(t.fuori,'attrezzatura',t.altro))v(id,tipo,ordine);
update public.mezzi_assegnazioni set dal='2026-11-01 00:00 Europe/Rome',al='2026-12-01 00:00 Europe/Rome' where mezzo_id=(select a1 from mezzo_test);
-- Legacy current placement has no historical assignment. Never edit real rows.
delete from public.mezzi_assegnazioni where mezzo_id=(select a2 from mezzo_test);
insert into public.mezzi(id,company_id,nome,tipo,su_mezzo_id) select t.child,f.company_id,'TEST MEZZI POS CARICATO','attrezzatura',t.parent from tecnica_test f cross join mezzo_test t;
insert into public.mezzi(id,company_id,nome,tipo,gestione,quantita_totale,unita_misura) select t.q,f.company_id,'TEST MEZZI POS QUANTITA','attrezzatura','quantita',10,'mq' from tecnica_test f cross join mezzo_test t;
insert into public.mezzi_allocazioni(company_id,mezzo_id,order_id,quantita,dal,al) select f.company_id,t.q,f.order_id,2.5,'2026-11-01','2026-11-30' from tecnica_test f cross join mezzo_test t;
update mezzo_test set fonte=(select public.pos_mezzo_fotografia(f.company_id,f.order_id,t.a1,'assegnazione',a.id) from tecnica_test f cross join mezzo_test t join public.mezzi_assegnazioni a on a.mezzo_id=t.a1);
update tecnica_test set contenuto=contenuto||jsonb_build_object('versione_mezzi',1,'opera',jsonb_build_object('data_inizio','2026-11-01','data_fine','2026-11-30'));
update tecnica_test set contenuto=jsonb_set(contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica}',jsonb_build_object('modalita','inventario','motivazione','','fonte',(select fonte from mezzo_test),'utilizzo_dal','2026-11-02','utilizzo_al','2026-11-20','quantita_usata',1,'confermata',true));
set local role authenticated;
do $$declare f record;t record;q jsonb;begin select * into f from tecnica_test;select * into t from mezzo_test;
 begin perform public.pos_mezzi_quadro(gen_random_uuid(),f.order_id);raise exception 'ASSERT: altra azienda';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
 begin perform public.pos_mezzi_quadro(f.company_id,f.order_id);raise exception 'ASSERT: soggetto senza accesso';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',f.actor,'role','authenticated')::text,true);
 q:=public.pos_mezzi_quadro(f.company_id,f.order_id);
 if exists(select 1 from jsonb_array_elements(q->'fonti') x where x->>'mezzo_id'=t.fuori::text) then raise exception 'ASSERT: altra commessa visibile';end if;
 if (select count(*) from jsonb_array_elements(q->'fonti') x where x->>'mezzo_id' in(t.a1::text,t.a2::text,t.q::text,t.child::text))<>4 then raise exception 'ASSERT: omonimi, quantità o carico persi';end if;
 if q::text like '%valore_acquisto%' or q::text like '%assegnato_hr_profilo_id%' or q::text like '%TEST NOTA PRIVATA%' then raise exception 'ASSERT: dati privati proiettati';end if;
 if (select x->>'al' from jsonb_array_elements(q->'fonti') x where x->>'mezzo_id'=t.a1::text)<>'2026-11-30' then raise exception 'ASSERT: fine assegnazione esclusiva non rispettata';end if;
 if (select x->>'dal' from jsonb_array_elements(q->'fonti') x where x->>'mezzo_id'=t.a2::text) is not null then raise exception 'ASSERT: periodo legacy inventato';end if;
 if has_function_privilege('authenticated','public.pos_mezzi_verifica(uuid,uuid,jsonb)','execute') or has_function_privilege('anon','public.pos_mezzi_quadro(uuid,uuid)','execute') then raise exception 'ASSERT: verifica privata esposta';end if;
end$$;
reset role;
set local role service_role;
do $$declare f record;t record;v jsonb;z jsonb;begin select * into f from tecnica_test;select * into t from mezzo_test;
 v:=public.pos_mezzi_verifica(f.company_id,f.order_id,f.contenuto);
 if jsonb_array_length(v->'collegamenti')<>1 then raise exception 'ASSERT: fonte non conservata';end if;
 z:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,fonte}',(select public.pos_mezzo_fotografia(f.company_id,f.order_id,t.q,'allocazione',a.id) from public.mezzi_allocazioni a where a.mezzo_id=t.q));
 z:=jsonb_set(z,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,quantita_usata}','2.5');perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);
 z:=jsonb_set(z,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,quantita_usata}','3');
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);raise exception 'ASSERT: oltre quantità allocata';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 z:=jsonb_set(jsonb_set(f.contenuto,'{opera,data_fine}','"2026-12-31"'),'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,utilizzo_al}','"2026-12-01"');
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);raise exception 'ASSERT: oltre periodo assegnazione';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 z:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,quantita_usata}','0.5');
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);raise exception 'ASSERT: frazione singola accettata';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 z:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,utilizzo_al}','"2026-12-01"');
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);raise exception 'ASSERT: periodo oltre POS';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 z:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,confermata}','false');
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);raise exception 'ASSERT: conferma implicita';exception when raise_exception then if sqlerrm like 'ASSERT:%' then raise;end if;end;
 z:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica,fonte,nome}','"NOME ALTERATO"');
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);raise exception 'ASSERT: fotografia alterata';exception when serialization_failure then null;end;
 z:=jsonb_set(f.contenuto,'{lavorazioni,0,tecnica,attrezzature,0,anagrafica}',jsonb_build_object('modalita','non_censita','motivazione','TEST titolare descritto nella scheda','fonte',null,'utilizzo_dal','2026-11-02','utilizzo_al','2026-11-20','quantita_usata',1,'confermata',true));
 perform public.pos_mezzi_verifica(f.company_id,f.order_id,z);
end$$;
reset role;
update public.mezzi set stato='in_officina' where id=(select a1 from mezzo_test);
set local role service_role;
do $$declare f record;begin select * into f from tecnica_test;
 begin perform public.pos_mezzi_verifica(f.company_id,f.order_id,f.contenuto);raise exception 'ASSERT: fonte cambiata durante emissione';exception when serialization_failure then null;end;
end$$;
reset role;
update public.mezzi set stato='in_servizio' where id=(select a1 from mezzo_test);
insert into public.pos_documents(id,company_id,order_id,tipo_lavori,indirizzo_cantiere,status,revisione,contenuto,iter,updated_at) select pos_id,company_id,order_id,'TEST MEZZI POS ROLLBACK','Indirizzo sintetico','bozza',0,contenuto,'{}',clock_timestamp() from tecnica_test;
do $$declare f record;begin select * into f from tecnica_test;
 begin update public.pos_documents set contenuto=contenuto-'versione_mezzi' where id=f.pos_id;raise exception 'ASSERT: downgrade accettato';exception when serialization_failure then null;end;
end$$;
alter table mezzo_test add column emissione jsonb,add column manifest jsonb;
update mezzo_test t set emissione=public.pos_prenota_emissione(f.pos_id,f.actor,p.updated_at,null),prova=public.pos_mezzi_fonti_emissione(f.pos_id,f.actor) from tecnica_test f join public.pos_documents p on p.id=f.pos_id;
update mezzo_test t set manifest=jsonb_build_object('emissioneId',t.emissione->>'id','companyId',f.company_id,'posId',f.pos_id,'revisione',0,'origine','approvazione_corrente','file',(select jsonb_agg(jsonb_build_object('nome',n,'path',f.company_id::text||'/'||(t.emissione->>'id')||'/'||(t.emissione->>'token')||'/'||n,'sha256',repeat('a',64),'dimensione',1))from unnest(array['POS.pdf','modello.html','fonti.json'])n))from tecnica_test f;
-- Storage metadata only: this does not test upload/download of physical files.
insert into storage.objects(bucket_id,name)select 'pos-emissioni',f.company_id::text||'/'||(t.emissione->>'id')||'/'||(t.emissione->>'token')||'/'||n from mezzo_test t cross join tecnica_test f cross join unnest(array['POS.pdf','modello.html','fonti.json','manifest.json','fascicolo.zip'])n;
set local role service_role;
do $$declare f record;t record;begin select * into f from tecnica_test;select * into t from mezzo_test;
 begin perform public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST',t.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: fonti mezzi nel manifest mancanti';exception when raise_exception then if sqlerrm<>'Il pacchetto non conserva identità e assegnazioni attrezzatura riesaminate' then raise;end if;end;
end$$;
reset role;
update mezzo_test set manifest=manifest||jsonb_build_object('mezzi_pos',prova);
do $$declare f record;t record;begin select * into f from tecnica_test;select * into t from mezzo_test;
 begin
  update public.mezzi_assegnazioni set al='2026-11-10 00:00 Europe/Rome' where mezzo_id=t.a1;
  perform public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST',t.manifest,repeat('b',64),repeat('c',64));raise exception 'ASSERT: assegnazione cambiata durante rendering';
 exception when serialization_failure then null;end;
end$$;
set local role service_role;
select public.pos_completa_emissione((t.emissione->>'id')::uuid,(t.emissione->>'token')::uuid,f.actor,'TEST MEZZI',t.manifest,repeat('b',64),repeat('c',64)) from mezzo_test t cross join tecnica_test f;
reset role;
do $$begin if not exists(select 1 from public.pos_documents p join tecnica_test f on f.pos_id=p.id where p.status='approvato') then raise exception 'ASSERT: finalizzazione non approva';end if;end$$;
select 'PASS: identità, omonimi, assegnazioni, quantità, carico corrente, ACL, privacy, conferme e fonti cambiate; rollback' as risultato;
rollback;
